L["affinityhelp.levels.title"] = "Growing Together"
L["affinityhelp.levels.text"] = "When they level up beside you, they remember who stood with them."
L["affinityhelp.class_quest.title"] = "Class Trials"
L["affinityhelp.class_quest.text"] = "Help with their class quests—the harder the trial, especially epic weapons and mounts, the deeper their gratitude."
L["affinityhelp.loan.title"] = "A Friend in Need"
L["affinityhelp.loan.text"] = "Lend them a hand with coin when they come up short; they won't forget the kindness."
L["affinityhelp.dungeon.title"] = "Dungeons"
L["affinityhelp.dungeon.text"] = "Clear a dungeon together at max level and fell the final boss. The first victory together leaves the deepest mark."
L["affinityhelp.raid.title"] = "Raids"
L["affinityhelp.raid.text"] = "Conquering a raid together means even more than a dungeon—just be sure to bring down the final boss."
L["affinityhelp.title"] = "Building Affinity"
L["affinityhelp.intro"] = "Affinity grows through shared journeys and hardships. The deeper the bond, the more they will entrust to you."
L["affinityhelp.foot"] = "Seasoned adventurers already know how to read people when you first meet."
L["affinityhelp.link"] = "How does affinity grow?"
L["affinityhelp.link.tip.title"] = "Building Affinity"
L["affinityhelp.link.tip.text"] = "Click to see what brings companions closer to you."
