L["guide.welcome.title"] = "Your First Companion"
L["guide.welcome.intro"] = "Congratulations! {name} is now your first companion.\nFrom here on, you'll brave Azeroth side by side."
L["guide.welcome.real.title"] = "A True Adventurer"
L["guide.welcome.real.text"] = "Like any adventurer in Azeroth, they carry their own weight—buying food and drink, stocking reagents, repairing worn armor, and earning their own coin. Every bit of strength they gain is earned together."
L["guide.welcome.grow.title"] = "Growing Alongside You"
L["guide.welcome.grow.text"] = "They level, quest, and delve into dungeons with you. When you part ways, they still have a life of their own."
L["guide.welcome.person.title"] = "A Mind of Their Own"
L["guide.welcome.person.text"] = "Each companion has their own temperament, strikes up conversation, and asks for help when needed. Whenever you'd like to talk, just speak with them."
L["guide.welcome.foot"] = "Click the Companions button below to meet them."
L["guide.welcome.ok"] = "Okay"
L["guide.arrow"] = "Your companions live here. Take a look."
L["guide.tour.slots"] = "This shows how many companions you can keep. More slots open up as you level."
L["guide.tour.list"] = "This is your companion roster. Select someone to see their details on the right."
L["guide.tour.affinity"] = "This shows their trust and affinity toward you. The closer you grow, the more they'll share—their packs, their craft, even their fate.\n\nFuture adventurers will travel with you on trial first before committing. The farther you journey together, the stronger the bond."
L["guide.tour.page"] = "{page}/{total}"
L["guide.tour.next"] = "Next"
L["guide.tour.done"] = "Got it"
