L["voiceoptions.quiet.tip"] = "Only what matters in a fight: pulls, waiting, crowd control, low mana, retreats, boss mechanics."
L["voiceoptions.normal"] = "Normal"
L["voiceoptions.normal.tip"] = "Also thanks and congratulations; chatty companions talk a little now and then."
L["voiceoptions.chatty"] = "Chatty"
L["voiceoptions.chatty.tip"] = "Everything: entering a dungeon, after a boss, and some idle talk."
L["voiceoptions.marks"] = "Raid marks on crowd-controlled enemies"
L["voiceoptions.marks.tip"] = "Enemies your companions sheep, sap or shackle get a mark (mage moon, rogue star, priest triangle...). Your own marks are left alone."
